  "claims": [
    {
      "claim": "The closest structural context, a fused pyrazolopyrimidinone lactam bearing a pyridine sulfonamide-linked basic piperazine, showed 34% oral bioavailability derived from IV and oral profiles in fasted healthy volunteers, directly supporting F >= 20% for a sulfonamide-linked basic amine on a fused lactam.",
      "card_ids": ["C02"]
    },
    {
      "claim": "Ziprasidone, a fused oxindole lactam with a basic piperazine side chain, had 30% fasted-state oral bioavailability and ~60% fed-state absolute bioavailability; L2 adds 60% absolute F for 20 mg fasted and a predicted 31% for 80 mg fasted, all above the 20% threshold.",
      "card_ids": ["C01", "C06", "C12", "C14", "C18", "C19", "C23", "C24"]
    },
    {
      "claim": "Praziquantel, an isoquinolinone-type lactam, retained 27.2 ± 5.4% oral bioavailability even in cirrhotic patients, supporting positive oral exposure for isoquinolinone-related structures.",
      "card_ids": ["C03"]
    },
    {
      "claim": "Other training contexts are also at or above threshold: niraparib ~73% fasted, didanosine 29 ± 6% fasted, thalidomide 80-100%, and gaboxadol high in humans with 83-110% in rats.",
      "card_ids": ["C08", "C05", "C09", "C16", "C13", "C20", "C25"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C18", "C19", "C20", "C21", "C22", "C23", "C24", "C25"]
    }
  ],
  "evidence_gaps": [
    "No direct query-specific oral bioavailability measurement is available.",
    "No human PK, formulation, prandial-state, or IV-comparison data for the exact query molecule are supplied.",
    "Metabolic stability, first-pass extraction, and transporter/efflux behavior for the query are not directly measured.",
    "The query's very low neutral fraction and logD -1.42 raise permeability uncertainty, but this is not affirmative evidence of F < 20%.",
    "Transfer from C02, ziprasidone, and praziquantel is structural/functional rather than an exact match."
  ],
  "decision_summary": "All relevant training contexts, including the closest sulfonamide-fused-lactam and isoquinolinone-type structures, report oral bioavailability at or above 20% (27-34% in fasted or diseased states; ziprasidone 30-60%; niraparib ~73%; didanosine 29 ± 6%). L2 records add further positive ziprasidone and gaboxadol context and do not provide affirmative low-F evidence for the query. The mixed physicochemical prior is insufficient to overturn this, so F >= 20% is better supported: prediction high with moderate confidence."
}

